import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { 
  Calendar, 
  Plus, 
  CheckCircle, 
  Clock, 
  AlertCircle,
  Filter,
  Search
} from 'lucide-react';
import { scheduleAPI } from '../services/api';
import toast from 'react-hot-toast';

const Schedule = () => {
  const [showAddModal, setShowAddModal] = useState(false);
  const [filterStatus, setFilterStatus] = useState('ALL');
  const [searchTerm, setSearchTerm] = useState('');

  const queryClient = useQueryClient();

  const { data: upcomingTasks = [], isLoading: upcomingLoading } = useQuery(
    'upcomingTasks', 
    scheduleAPI.getUpcoming
  );

  const { data: weeklyTasks = [], isLoading: weeklyLoading } = useQuery(
    'weeklyTasks', 
    scheduleAPI.getWeekly
  );

  const markCompleteMutation = useMutation(scheduleAPI.markComplete, {
    onSuccess: () => {
      queryClient.invalidateQueries('upcomingTasks');
      queryClient.invalidateQueries('weeklyTasks');
      toast.success('Task marked as completed');
    },
    onError: () => {
      toast.error('Failed to update task');
    }
  });

  const allTasks = [...upcomingTasks, ...weeklyTasks];
  const uniqueTasks = allTasks.filter((task, index, self) => 
    index === self.findIndex(t => t.id === task.id)
  );

  const filteredTasks = uniqueTasks.filter(task => {
    const matchesSearch = task.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         task.description?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = filterStatus === 'ALL' || 
                         (filterStatus === 'PENDING' && !task.completed) ||
                         (filterStatus === 'COMPLETED' && task.completed);

    return matchesSearch && matchesStatus;
  });

  const handleMarkComplete = (taskId) => {
    markCompleteMutation.mutate(taskId);
  };

  const getStatusClass = (task) => {
    if (task.completed) return 'status-completed';

    const taskDate = new Date(task.scheduledDate);
    const today = new Date();
    const diffTime = taskDate - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return 'status-overdue';
    if (diffDays <= 1) return 'status-pending';
    return 'status-pending';
  };

  const getStatusText = (task) => {
    if (task.completed) return 'Completed';

    const taskDate = new Date(task.scheduledDate);
    const today = new Date();
    const diffTime = taskDate - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return 'Overdue';
    if (diffDays === 0) return 'Today';
    if (diffDays === 1) return 'Tomorrow';
    return `In ${diffDays} days`;
  };

  const getPriorityClass = (priority) => {
    switch (priority) {
      case 'HIGH': return 'priority-high';
      case 'MEDIUM': return 'priority-medium';
      case 'LOW': return 'priority-low';
      default: return 'priority-medium';
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">
            <Calendar className="farm-icon" />
            Breeding Schedule
          </h1>
          <p className="page-subtitle">
            Manage your breeding activities and farm tasks.
          </p>
        </div>
        <button 
          className="btn-primary"
          onClick={() => setShowAddModal(true)}
        >
          <Plus size={16} />
          Add Task
        </button>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <Search size={20} />
          <input
            type="text"
            placeholder="Search tasks..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>

        <div className="filter-group">
          <Filter size={16} />
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="filter-select"
          >
            <option value="ALL">All Tasks</option>
            <option value="PENDING">Pending</option>
            <option value="COMPLETED">Completed</option>
          </select>
        </div>
      </div>

      <div className="schedule-content">
        <div className="tasks-section">
          <div className="section-card">
            <h2 className="section-title">
              <Clock className="farm-icon" />
              All Tasks
            </h2>

            {upcomingLoading || weeklyLoading ? (
              <div className="loading-container">
                <div className="loading-spinner"></div>
                <p>Loading tasks...</p>
              </div>
            ) : filteredTasks.length > 0 ? (
              <div className="tasks-list">
                {filteredTasks.map((task) => (
                  <div key={task.id} className="schedule-item">
                    <div className="task-info">
                      <div className="task-title">{task.title || 'Breeding Task'}</div>
                      <div className="task-details">
                        <div className="task-date">
                          <Calendar size={14} />
                          {new Date(task.scheduledDate).toLocaleDateString()}
                        </div>
                        {task.description && (
                          <div className="task-description">
                            {task.description}
                          </div>
                        )}
                        {task.priority && (
                          <div className={`task-priority ${getPriorityClass(task.priority)}`}>
                            {task.priority}
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="task-actions">
                      <div className={`task-status ${getStatusClass(task)}`}>
                        {getStatusText(task)}
                      </div>
                      {!task.completed && (
                        <button
                          className="btn-primary btn-sm"
                          onClick={() => handleMarkComplete(task.id)}
                          disabled={markCompleteMutation.isLoading}
                        >
                          <CheckCircle size={14} />
                          Complete
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="empty-state">
                <Calendar className="empty-state-icon" />
                <h3 className="empty-state-title">No Tasks Found</h3>
                <p className="empty-state-description">
                  {searchTerm || filterStatus !== 'ALL'
                    ? 'Try adjusting your search or filters.'
                    : 'Create your first breeding task to get started.'
                  }
                </p>
                {!searchTerm && filterStatus === 'ALL' && (
                  <button 
                    className="btn-primary"
                    onClick={() => setShowAddModal(true)}
                  >
                    <Plus size={16} />
                    Add First Task
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="stats-section">
          <div className="section-card">
            <h2 className="section-title">
              <AlertCircle className="farm-icon" />
              Task Overview
            </h2>

            <div className="stats-grid">
              <div className="stat-item">
                <div className="stat-value">
                  {filteredTasks.filter(t => !t.completed).length}
                </div>
                <div className="stat-label">Pending Tasks</div>
              </div>

              <div className="stat-item">
                <div className="stat-value">
                  {filteredTasks.filter(t => t.completed).length}
                </div>
                <div className="stat-label">Completed</div>
              </div>

              <div className="stat-item">
                <div className="stat-value">
                  {filteredTasks.filter(t => {
                    const taskDate = new Date(t.scheduledDate);
                    const today = new Date();
                    return taskDate < today && !t.completed;
                  }).length}
                </div>
                <div className="stat-label">Overdue</div>
              </div>

              <div className="stat-item">
                <div className="stat-value">
                  {filteredTasks.filter(t => {
                    const taskDate = new Date(t.scheduledDate);
                    const today = new Date();
                    const diffTime = taskDate - today;
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    return diffDays >= 0 && diffDays <= 7 && !t.completed;
                  }).length}
                </div>
                <div className="stat-label">This Week</div>
              </div>
            </div>
          </div>

          <div className="section-card">
            <h2 className="section-title">
              <Clock className="farm-icon" />
              Quick Actions
            </h2>

            <div className="quick-actions">
              <button className="btn-secondary">
                <Calendar size={16} />
                Schedule Breeding
              </button>
              <button className="btn-secondary">
                <CheckCircle size={16} />
                Mark All Complete
              </button>
              <button className="btn-secondary">
                <AlertCircle size={16} />
                View Overdue
              </button>
            </div>
          </div>
        </div>
      </div>

      {showAddModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2 className="modal-title">Add New Task</h2>
              <button 
                className="modal-close"
                onClick={() => setShowAddModal(false)}
              >
                ×
              </button>
            </div>
            <div className="modal-body">
              <p>Add task form will be implemented here.</p>
              <button 
                className="btn-primary"
                onClick={() => {
                  setShowAddModal(false);
                  toast.info('Add task form coming soon');
                }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Schedule;
